assert len(ADD) == 50, len(ADD)
n = 0
for eid, secs in ADD.items():
    x = E[eid]
    have = {s['title'] for s in x['sections']}
    sids = x['sourceIds']
    for title, text, pos in secs:
        assert title not in have, (eid, title)
        s = {'title': title, 'text': text, 'sourceIds': sids}
        if pos is None:
            x['sections'].append(s)
        else:
            x['sections'].insert(pos, s)
        have.add(title)
        n += 1
    assert len(x['sections']) >= 5, (eid, len(x['sections']))
